/**
 * Lighthouse CI configuration for sites generated by AI Theme Studio.
 *
 *   ATS_LH_URLS="https://example.test/,https://example.test/services/" npm run lighthouse:mobile
 *   ATS_LH_URLS="..." npm run lighthouse:desktop
 *
 * Targets: Performance >= 90, Accessibility >= 95, Best Practices >= 95, SEO >= 95.
 * Pages must be published and publicly reachable (drafts redirect to login).
 */
const urls = ( process.env.ATS_LH_URLS || '' )
	.split( ',' )
	.map( ( u ) => u.trim() )
	.filter( Boolean );

if ( ! urls.length ) {
	throw new Error( 'Set ATS_LH_URLS to a comma-separated list of published page URLs.' );
}

const desktop = 'desktop' === process.env.ATS_LH_PRESET;

module.exports = {
	ci: {
		collect: {
			url: urls,
			numberOfRuns: Number( process.env.ATS_LH_RUNS || 3 ),
			settings: {
				preset: desktop ? 'desktop' : undefined,
				locale: process.env.ATS_LH_LOCALE || 'fa',
				chromeFlags: '--no-sandbox --headless=new',
				skipAudits: [ 'uses-http2' ],
			},
		},
		assert: {
			assertions: {
				'categories:performance': [ 'error', { minScore: 0.9, aggregationMethod: 'median-run' } ],
				'categories:accessibility': [ 'error', { minScore: 0.95, aggregationMethod: 'median-run' } ],
				'categories:best-practices': [ 'error', { minScore: 0.95, aggregationMethod: 'median-run' } ],
				'categories:seo': [ 'error', { minScore: 0.95, aggregationMethod: 'median-run' } ],
				'largest-contentful-paint': [ 'warn', { maxNumericValue: desktop ? 1200 : 2500 } ],
				'cumulative-layout-shift': [ 'warn', { maxNumericValue: 0.1 } ],
				'total-blocking-time': [ 'warn', { maxNumericValue: desktop ? 150 : 200 } ],
				'dom-size': [ 'warn', { maxNumericValue: 1400 } ],
				'heading-order': 'error',
				'image-alt': 'error',
				'document-title': 'error',
				'meta-description': 'error',
				'link-text': 'warn',
				'color-contrast': 'error',
			},
		},
		upload: {
			target: 'filesystem',
			outputDir: `.lighthouseci/${ desktop ? 'desktop' : 'mobile' }`,
		},
	},
};
